            //
            aIngress = RotL64(aFireLaneC[((aIndex + 30778U)) & S_BLOCK1], 24U) ^ RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 28402U)) & S_BLOCK1], 53U);
            aIngress = TwistMix64::DiffuseB(((aIngress ^ aDomainWordIngress) ^ aNonceWordO));
