            aCross = RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 28548U)) & S_BLOCK1], 30U) ^ RotL64(aEarthLaneB[((S_BLOCK1 - aIndex + 28390U)) & S_BLOCK1], 11U);
