            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x6AD9A45B4E67C5BAULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x02349349DF185D4DULL;
            aOrbiterC = RotL64((aOrbiterC * 0x82BA2E64C8299171ULL), 27U);
