            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x15F244B7497C1ECBULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0xB694B861036C3E09ULL) ^ aNonceWordA;
            aOrbiterB = RotL64((aOrbiterB * 0xEC60E0A3546D1737ULL), 51U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x3B1C8B02CED8CD3EULL;
