            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x9D5B66DC06F2B876ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xFB7348144E28F0C6ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x834198384390D24BULL), 57U);
