            aOrbiterJ = (((aOrbiterJ ^ aOrbiterI) ^ 0x28E5DEE3F2ED121CULL) ^ aPhaseAOrbiterUpdateSaltD[((aIndex + 29U)) & S_SALT1]) ^ aNonceWordB;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCA15EAD79235C9CBULL), 3U);
