            aCross = (RotL64(aIceLaneB[((S_BLOCK1 - aIndex + 32429U)) & S_BLOCK1], 34U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 24962U)) & S_BLOCK1], 21U));
            aCross ^= (RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 29732U)) & S_BLOCK1], 11U) ^ RotL64(aWaterLaneB[((aIndex + 31381U)) & S_BLOCK1], 53U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aPrevious, 48U) ^ RotL64(aCross, 23U)) + (RotL64(aIngress, 11U) + RotL64(aCarry, 35U));
