            //
            aOrbiterD = (((aWandererH + RotL64(aCross, 11U)) + RotL64(aCarry, 5U)) + 0xEEF02E5FABEF6A6DULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 9U)) & S_SALT1];
            aOrbiterA = (aWandererK + RotL64(aIngress, 47U)) + 0xC34DA87748D55887ULL;
            aOrbiterK = (aWandererG + RotL64(aScatter, 21U)) + 0x61E63F620B77032AULL;
            aOrbiterC = (((aWandererJ + RotL64(aPrevious, 27U)) + RotL64(aCarry, 57U)) + 0x8BA9529C68F235AFULL) + aPhaseAOrbiterAssignSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aScatter, 5U)) + 0x7E7C08B8DBCD0992ULL;
            aOrbiterF = (aWandererB + RotL64(aPrevious, 60U)) + 0x0CA57E45E6B658B3ULL;
            aOrbiterJ = ((aWandererF + RotL64(aIngress, 41U)) + RotL64(aCarry, 37U)) + 0x3D1F4D4220E9163DULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x9B8192CCF5348EB1ULL) + aPhaseAOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xDE4B63BD861F0243ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x0C313AC1BC19382FULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xFA8467242AFC49CCULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterA) ^ 0x18B64B7011FBE768ULL) ^ aPhaseAOrbiterUpdateSaltD[((aIndex + 10U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xF078C2BD5AB8629BULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xD57C8E2DB64BC9DCULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x42215040521E0FBBULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x4D87E809DF2C9C8DULL), 5U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0xC6563CF5860ADA35ULL) + aPhaseAOrbiterUpdateSaltC[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0xE6CD73DAA61EF626ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x9ABF409D536BFBBDULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x1E56469491A0B9A7ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x6BE2267D0FD968D1ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xE97F36B0C09966B1ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x3194FD1458CC12B6ULL) + aPhaseAOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x11BD3633AD68FA0CULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9A904C754979C967ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x5CC40580C45F3765ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xBCEA4643EA88B964ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB3B5F77089EDA8A7ULL), 13U);
