            aWandererK = aWandererK + (((RotL64(aIngress, 19U) + aOrbiterD) + RotL64(aOrbiterJ, 5U)) + RotL64(aCarry, 13U));
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 5U) + aOrbiterD) + RotL64(aOrbiterA, 29U));
            aWandererB = aWandererB + ((((RotL64(aScatter, 29U) + aOrbiterG) + RotL64(aOrbiterK, 35U)) + RotL64(aCarry, 51U)) + aPhaseAWandererUpdateSaltC[(((31U - aIndex) + 13U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aCross, 13U) + aOrbiterF) + RotL64(aOrbiterC, 41U)) + aPhaseAWandererUpdateSaltA[(((31U - aIndex) + 17U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aIngress, 57U) + aOrbiterD) + RotL64(aOrbiterF, 13U));
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 37U) + RotL64(aOrbiterC, 19U)) + aOrbiterA);
            aWandererH = aWandererH + ((RotL64(aCross, 46U) + RotL64(aOrbiterG, 50U)) + aOrbiterF);
